{
  "name": "opencode-plugin-peers",
  "version": "0.2.4",
  "description": "Cross-session messaging for opencode — let independent sessions discover and text each other, modeled after Claude Code's cross-session messaging",
  "type": "module",
  "main": "./dist/index.js",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/tui.d.ts",
      "import": "./dist/tui.js"
    },
    "./commands/peers.md": "./commands/peers.md",
    "./commands/list-agents.md": "./commands/list-agents.md",
    "./commands/peers-name.md": "./commands/peers-name.md",
    "./commands/peers-inbox.md": "./commands/peers-inbox.md",
    "./commands/peers-outbox.md": "./commands/peers-outbox.md",
    "./commands/*": "./commands/*"
  },
  "files": [
    "dist",
    "commands",
    "README.md",
    "README.zh-CN.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "claude-code",
    "cross-session",
    "messaging",
    "multi-agent",
    "ai-coding-agent"
  ],
  "license": "MIT",
  "author": {
    "name": "opencode-plugin-peers authors"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/jkrandom-sudo/opencode-plugin-peers.git"
  },
  "bugs": {
    "url": "https://github.com/jkrandom-sudo/opencode-plugin-peers/issues"
  },
  "homepage": "https://github.com/jkrandom-sudo/opencode-plugin-peers#readme",
  "engines": {
    "node": ">=18",
    "opencode": ">=1.18.0"
  },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "prepare": "npm run build",
    "test": "npm run build && node --test tests/*.test.mjs",
    "typecheck": "tsc --noEmit -p tsconfig.json",
    "dry-run": "npm publish --dry-run",
    "prepublishOnly": "npm run build"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.0"
  },
  "dependencies": {
    "zod": "^4.1.8"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.0",
    "@opentui/core": "^0.4.5",
    "@opentui/keymap": "^0.4.5",
    "@opentui/solid": "^0.4.5",
    "@types/node": "^22.0.0",
    "typescript": "^5.4.0"
  },
  "opencode": {
    "plugin": true,
    "commands": [
      "commands/peers.md",
      "commands/list-agents.md",
      "commands/peers-name.md",
      "commands/peers-inbox.md",
      "commands/peers-outbox.md"
    ]
  }
}
